# region: gather
def gather(raw):
    out = []
    for tok in raw[1:]:
        s = tok.strip()
        if s.isdigit() and int(s) > 0:
            out.append(int(s))
    return out

# region: shape
def shape(xs):
    return [v * v for v in xs]

# region: fold
def fold(xs, offset=-1):
    return [v + offset for v in xs]

# region: emit
def emit(xs):
    return {'n': len(xs), 'total': sum(xs)}

# region: sift
def sift(summary, name='gamma'):
    out = dict(summary)
    out['label'] = name.upper() if summary.get('n', 0) else 'EMPTY'
    return out

# region: run
def run(raw):
    return sift(emit(fold(shape(gather(raw)))))

